    } });
  vm.runInContext(transportSource, context);
  return { requests, request: options => context.AgentTransport.requestPlan({ provider: 'api', base: 'https://gateway.example.invalid/v1/responses', model: 'fixture-model', token: '[REDACTED]', input: input('请分析'), ...options }) };
