 assert.equal(W.resolveLink(state,'a','../methods/b.md'),'b');
 assert.equal(W.resolveLink(state,'a','../../etc/passwd'),null);
 assert.equal(W.resolveLink(state,'a','https://example.com/methods/b.md'),null);
